package net.officefloor.hq.app.holiday;

import java.util.List;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class RespondWithHolidays {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(value = "asOf", required = false) String asOf, Holidays holidays, AsOf asOfSheet,
            ObjectResponse<List<HolidayResponse>> response) throws InvalidSheetRequestException {
        response.send(asOfSheet.view(sheetId, asOf,
                () -> holidays.onSheet(sheetId).stream().map(HolidayResponse::from).toList()));
    }
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
export class HttpError extends Error {
  constructor(message: string, readonly status: number, readonly body: string) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  // While this screen shows the sheet as of a date (the `asof` search param, see
  // features/asof/useAsOf.ts) every change is refused, before it reaches the store.
  if (init?.method !== undefined && init.method !== 'GET' && asOfSet()) {
    throw new HttpError(`${init.method} ${path} refused: the sheet is shown as of a date`, 409, '');
  }
  const res = await fetch(path, init);
  if (!res.ok) {
    const body = await res.text().catch(() => '');
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status, body);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

function asOfSet(): boolean {
  return (new URLSearchParams(window.location.search).get('asof') ?? '') !== '';
}
