import { defineSlot } from '../Slot';

/**
 * The active sheet's content on the home screen. Rendered only once someone is signed in and a
 * sheet is loaded; everything kept per sheet contributes a panel here, keyed by `sheet`.
 */
export const SheetPanels = defineSlot<{ user: string; sheet: string }>('sheet.panels');
src/main/frontend/features/summary/summary.slot.tsx:119:export const contribution = SheetPanels.fill({ order: 25, Component: SummaryPanel });
src/main/frontend/features/tags/tags.slot.tsx:51:export const contribution = SheetPanels.fill({ order: 26, Component: TagsPanel });
src/main/frontend/features/months/months.slot.tsx:51:export const contribution = SheetPanels.fill({ order: 27, Component: MonthsPanel });
package net.officefloor.hq.app.person;

import java.util.List;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class RespondWithWatches {
    public void respond(@PathVariable("sheetId") String sheetId, @RequestParam(value = "user", required = false) String user,
            @RequestParam(value = "asOf", required = false) String asOf, Watches watches, AsOf asOfSheet,
            ObjectResponse<List<Long>> response) throws InvalidSheetRequestException {
        response.send(user == null || user.isBlank() ? List.of()
                : asOfSheet.view(sheetId, asOf, () -> watches.watchedBy(sheetId, user.trim())));
    }
}

